'use strict';
const basePath = new URL('../', document.currentScript.src).pathname.replace(/\/$/, '');
const $ = selector => document.querySelector(selector);
const app = $('#app');
const uid = () => typeof crypto.randomUUID === 'function' ? crypto.randomUUID() : Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');
const state = {user:null,page:'overview',data:null,model:null,recipients:[],busy:false,selectedModel:'isolation_forest',researchUser:'demo-irfan',slide:0,lastScenario:null,pending:null};
const paths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',send:'m22 2-7 20-4-9-9-4L22 2ZM11 13 22 2',shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7l-9-4Zm-4 9 3 3 5-6',science:'M9 3h6m-5 0v6l-6 10a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2L14 9V3M8 14h8',arrow:'M5 12h14m-5-5 5 5-5 5',check:'m5 12 4 4L19 6',clock:'M12 8v4l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',logout:'M9 4H4v16h5m0-8h12m-4-4 4 4-4 4',card:'M3 5h18v14H3zM3 10h18m-13 5h3',activity:'M2 12h4l3-8 6 16 3-8h4',lock:'M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5zM12 14v3',alert:'m12 3 10 18H2L12 3Zm0 6v5m0 3v.1',calendar:'M5 5h14v16H5zM5 10h14M8 3v4m8-4v4',present:'M3 3h18v13H3zM12 16v5m-4 0h8M7 12l3-3 3 2 4-5'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.shield}"/></svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Format only user-facing prose; stored fields and wire identifiers stay intact.
const displayText=value=>String(value??'').replace(/synthetic/gi,'generated').replace(/sintetik/gi,'generated').replace(/Complete behavioural modalities are unavailable; no biometric inference made\.\s*Additional verification required\.?/gi,'Some required behavioural measurements are missing. Additional verification is required.');
const money=minor=>new Intl.NumberFormat('en-MY',{style:'currency',currency:'MYR'}).format((minor||0)/100);
const pct=value=>value!==null&&value!==undefined&&Number.isFinite(Number(value))?(Number(value)*100).toFixed(1)+'%':'—';
const raw=value=>value!==null&&value!==undefined&&Number.isFinite(Number(value))?Number(value).toFixed(4):'—';
const scoreText=(item,key)=>item?.decision_details?.score_available===false||item?.score_available===false?'Not assessed':key==='model_score'?raw(item?.[key]??item?.decision_details?.[key]):pct(item?.[key]??item?.decision_details?.[key]);
const date=value=>new Date(value).toLocaleString('en-MY',{timeZone:'Asia/Kuala_Lumpur',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const initials=value=>String(value||'').split(' ').slice(0,2).map(x=>x[0]).join('');
const syntheticMode=()=>String(state.model?.data_source||'').startsWith('synthetic');
const dataBadge=()=>!state.model?'RESEARCH DATA':syntheticMode()?'GENERATED REFERENCE DATA':'IMPORTED CSV';
const dataNarrative=()=>syntheticMode()?'Repeatable generated reference data; no real participant measurements are included. Public research datasets have not yet been imported.':'Imported CSV data. Its provenance, licence, feature mapping and labels require separate validation; importing a file does not establish that it contains genuine human measurements.';
const modelName=key=>({isolation_forest:'Isolation Forest',one_class_svm:'One-Class SVM','account-pin-synthetic-v1':'PIN rhythm check',not_scored:'Verification check',policy_only:'Account security check'}[key])||displayText(state.model?.model_names?.[key]||key);
const labels={overview:'Overview',transfer:'Transfer money',security:'Security centre',lab:'Research lab',presentation:'Presentation mode',admin:'Security overview'};
const tierLabel=tier=>({allow:'Low · Allow',step_up:'Medium · Verify',block:'High · Block',enrollment_required:'Baseline unavailable'}[tier]||tier||'—');
const statusLabel=status=>({completed:'Completed',blocked:'Blocked',pending:'Awaiting verification',step_up_required:'Awaiting verification',cancelled:'Cancelled',enrollment_required:'Enrolment required'}[status]||status);
const isLocked=()=>state.user?.status==='locked';
function tag(text,color=''){return `<span class="status-tag ${color}">${esc(text)}</span>`;}
function sectionTitle(title,description=''){return `<div class="section-head"><div><h2>${esc(title)}</h2>${description?`<p>${esc(description)}</p>`:''}</div></div>`;}
function greeting(title,description){return `<div class="greeting"><div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="date-pill">${icon('calendar')} ${new Date().toLocaleDateString('en-MY',{timeZone:'Asia/Kuala_Lumpur',day:'numeric',month:'short',year:'numeric'})}</div></div>`;}
async function api(path,body,method){
  const response=await fetch(basePath+'/api'+path,{method:method||(body?'POST':'GET'),credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});
  let data;try{data=await response.json();}catch{throw new Error(`The server returned an invalid response (${response.status}).`);}
  if(!response.ok){const error=new Error(typeof data.detail==='string'?displayText(data.detail):'Check the form details and try again.');error.status=response.status;throw error;}return data;
}
let toastTimer;
function toast(message){$('#toast').textContent=displayText(message);$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),6000);}
function modal(title,message,rows=[],tone='',actions=''){
  $('#dialog-content').innerHTML=`<div class="result-icon ${tone}">${icon(tone==='red'?'lock':tone==='amber'?'shield':'check')}</div><h2 id="dialog-title">${esc(title)}</h2><p>${esc(displayText(message))}</p>${rows.map(([a,b])=>`<div class="result-detail"><span class="muted">${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('')}${actions}<br>`;
  $('#dialog-close').textContent='Got it';if(!$('#result-dialog').open)$('#result-dialog').showModal();
}
$('#dialog-close').onclick=()=>$('#result-dialog').close();
function authScreen(register=false){
  app.innerHTML=`<main class="auth-layout"><section class="auth-story"><div class="brand"><img src="${basePath}/assets/icon.svg" alt="">purple<b>bank.</b></div><h1>Beyond the<br>password.<br><em>Understand the rhythm.</em></h1><p>A research banking prototype that examines changes in behaviour during account use. Per-user reference models support risk-based transaction decisions.</p><div class="auth-badge">${icon('science')} Isolation Forest + One-Class SVM · Per-user baseline</div></section><section class="auth-card"><h2>${register?'Create simulation account':'Welcome back'}</h2><p>${register?'New accounts need an enrolled reference before personal behavioural checks are available.':'Sign in to your account or explore the research presentation.'}</p><form id="auth-form">${register?'<div class="form-field"><label for="full-name">Account name</label><input id="full-name" name="full_name" autocomplete="name" minlength="2" maxlength="80" required></div>':''}<div class="form-field"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="username" maxlength="254" required placeholder="you@example.com"></div><div class="form-field"><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="${register?'new-password':'current-password'}" minlength="${register?12:1}" maxlength="128" placeholder="${register?'At least 12 characters':'Enter your password'}" required></div><div class="form-error" id="auth-error" role="alert"></div><button class="btn primary full" type="submit">${register?'Create simulation account':'Sign in securely'} ${icon('arrow')}</button></form>${!register?'<div class="divider">RESEARCH DEMONSTRATION</div><div class="demo-shortcuts"><button class="btn soft" id="demo-customer">Customer demo</button><button class="btn" id="demo-admin">Security admin demo</button></div><p class="small muted" style="margin-top:12px">After signing in, choose <strong>Presentation mode</strong> for a step-by-step guide.</p>':''}<p class="auth-note">Research prototype with simulated funds. Demonstration account passwords are public. The Research lab explains the reference data. Do not enter real banking credentials.</p><div class="auth-switch">${register?'Already have an account?':'Need your own test account?'} <button class="text-button" id="auth-switch">${register?'Sign in':'Create account'}</button></div></section></main>`;
  const pinLink=document.createElement('a');pinLink.href=basePath+'/pin-demo';pinLink.className='btn soft full';pinLink.textContent='PIN rhythm practice · Reference data';app.querySelector('.auth-card').append(pinLink);
  $('#auth-switch').onclick=()=>authScreen(!register);
  if(!register){$('#demo-customer').onclick=()=>{$('#email').value='irfan@purple.demo';$('#password').value='PurpleDemo!2026';$('#auth-form').requestSubmit();};$('#demo-admin').onclick=()=>{$('#email').value='admin@purple.demo';$('#password').value='PurpleAdmin!2026';$('#auth-form').requestSubmit();};}
  $('#auth-form').onsubmit=async e=>{
    e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;$('#auth-error').textContent='';
    const values=Object.fromEntries(new FormData(e.target));
    try{
      let device=values.email.trim().toLowerCase()==='irfan@purple.demo'?'purple-demo-browser':localStorage.getItem('purple_device_id');if(!device){device=uid();localStorage.setItem('purple_device_id',device);}
      if(register){const result=await api('/auth/register',{...values,device_id:device});authScreen();toast(result.message);return;}
      const result=await api('/auth/login',{...values,device_id:device});state.user=result.user;state.page=state.user.role==='admin'?'admin':'overview';state.pending=null;await refresh();
    }catch(error){if($('#auth-error'))$('#auth-error').textContent=error.message;}finally{button.disabled=false;}
  };
}
async function refresh(){
  if(state.user.role==='admin')state.data=await api('/admin/overview');
  else [state.data,state.recipients]=await Promise.all([api('/overview'),api('/recipients')]);
  if(state.data.user)state.user=state.data.user;
  state.model=await api('/model');
  if($('#data-source-banner'))$('#data-source-banner').textContent=syntheticMode()?'Generated reference data · Simulated funds · Research prototype':'Imported CSV · Provenance requires review · Simulated funds';
  const pending=state.data.pending_challenges?.[0];if(state.user.role==='customer')state.pending=pending?{...pending,challenge_id:pending.challenge_id||pending.id}:null;
  render();
}
function shell(content){
  const admin=state.user.role==='admin';const nav=admin?[['admin','grid'],['lab','science'],['presentation','present']]:[['overview','grid'],['transfer','send'],['security','shield'],['lab','science'],['presentation','present']];
  return `<div class="shell ${state.page==='presentation'?'presentation-shell':''}"><aside class="sidebar"><div><div class="brand"><img src="${basePath}/assets/icon.svg" alt="">purple<b>bank.</b></div><div class="brand-label">BEHAVIOURAL BIOMETRICS / FYP</div></div><div><div class="nav-label">${admin?'SECURITY CONSOLE':'WORKSPACE'}</div><nav class="nav" aria-label="Main navigation">${nav.map(([page,svg])=>`<button data-page="${page}" class="${page===state.page?'active':''}" ${page===state.page?'aria-current="page"':''}>${icon(svg)} ${labels[page]}</button>`).join('')}</nav></div><div class="sidebar-bottom"><div class="protection-note">${icon('science')}<h3>Learn the user’s patterns.</h3><p>Genuine sessions for training. Impostor sessions for testing only.</p></div><div class="profile"><div class="avatar">${esc(initials(state.user.full_name))}</div><div class="profile-info"><strong>${esc(state.user.full_name)}</strong><span>${admin?'Security administrator':'Simulation account'}</span></div><button class="icon-button" data-logout aria-label="Sign out">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Purple Bank <span class="muted"> / </span><strong>${labels[state.page]}</strong></div><div class="topbar-right"><span class="tag"><span class="live-dot"></span> ${esc(dataBadge())}</span><button class="icon-button" data-logout aria-label="Sign out">${icon('logout')}</button><div class="avatar">${esc(initials(state.user.full_name))}</div></div></header><div class="content">${content}<footer class="footer"><span>${icon('science')} Research prototype · Simulated funds · Anomaly scores do not establish identity</span><span>Isolation Forest + One-Class SVM · Per-user</span></footer></div></main></div>`;
}
function lockedNotice(){return isLocked()?`<div class="notice locked">${icon('lock')} <strong>Account locked.</strong> A high-risk transfer was blocked without moving funds. An administrator must review the account before unlocking it.</div>`:'';}
function pendingNotice(){return state.pending?`<div class="notice stepup-notice">${icon('shield')} <strong>Additional verification required.</strong> Funds have not moved. <button class="text-button" data-resume-stepup>Review pending transfer →</button></div>`:'';}
function coldStartNotice(){return state.user.role==='customer'&&!state.model?.users?.[state.user.id]?`<div class="notice"><strong>Behavioural reference unavailable.</strong> An account PIN or phone biometric does not train a behavioural model. This web flow needs an enrolled reference. For a separate two-person exercise, <a href="${basePath}/pin-demo">open PIN rhythm practice</a> with generated reference data. Use practice PIN 246810, not your transaction PIN. This exercise does not verify identity or move funds.</div>`:'';}
function transferForm(){return `<form id="transfer-form"><div class="field-row"><div><label for="recipient">Recipient</label><select id="recipient" name="recipient_id" required>${state.recipients.map(r=>`<option value="${esc(r.id)}">${esc(r.full_name)}</option>`).join('')}</select></div><div><label for="amount">Simulation amount</label><div class="input-prefix"><span>RM</span><input id="amount" name="amount" type="text" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" maxlength="12" placeholder="0.00" required></div></div></div><p class="form-explanation">The browser cannot measure every phone sensor. Incomplete behavioural data requires additional verification. The guided scenarios illustrate all three risk levels.</p><div class="form-error" id="transfer-error" role="alert"></div><div class="transfer-footer"><span class="small">${icon('shield')} Server-verified decision</span><button class="btn primary" type="submit" ${isLocked()?'disabled':''}>Review & send ${icon('arrow')}</button></div></form>`;}
function transactions(){return `<div class="table-wrap"><table><thead><tr><th>RECIPIENT / REFERENCE</th><th>STATUS</th><th>AMOUNT</th></tr></thead><tbody>${(state.data.transactions||[]).map(t=>`<tr><td><div class="recipient-cell"><div class="avatar">${icon(t.status==='blocked'?'lock':'send')}</div><div><strong>${esc(t.recipient_name)}</strong><small>${date(t.created_at)} · ${esc(t.id.slice(0,8))}</small></div></div></td><td>${tag(statusLabel(t.status),t.status==='blocked'?'red':['pending','step_up_required','enrollment_required'].includes(t.status)?'amber':'')}</td><td class="amount">${t.status==='completed'?'− ':''}${money(t.amount_minor)}</td></tr>`).join('')}</tbody></table>${!state.data.transactions?.length?`<div class="empty">${icon('send')}No transfers yet.<br>Try the normal scenario in Security centre.</div>`:''}</div>`;}
function timeline(events,limit=5){return (events||[]).slice(0,limit).map(e=>`<div class="timeline-item ${e.severity==='critical'?'critical':''}"><strong>${esc(displayText(e.kind.replaceAll('_',' ')))}</strong><p>${esc(displayText(e.reasons?.[0]))}</p><small>${date(e.created_at)} · percentile ${scoreText(e,'risk_score')} · raw score ${scoreText(e,'model_score')}</small></div>`).join('')||'<div class="empty">No decisions recorded yet.</div>';}
function overview(){return greeting(`Hello, ${state.user.full_name.split(' ')[0]} 👋`,'Your simulation account. Each transfer is checked before the balance changes.')+lockedNotice()+pendingNotice()+coldStartNotice()+`<section class="cards"><div class="card balance-card"><div class="card-head"><span>Available balance</span>${icon('card')}</div><div class="balance"><span>MYR</span>${new Intl.NumberFormat('en-MY',{minimumFractionDigits:2}).format(state.user.balance_minor/100)}</div><div class="account-number"><span>${esc(state.user.account_no)}</span><span>SIMULATION ACCOUNT</span></div></div><div class="card"><div class="card-head"><span>Account status</span><div class="status-icon ${isLocked()?'red':''}">${icon(isLocked()?'lock':'shield')}</div></div><div class="metric-value">${isLocked()?'Locked':'Active'}</div>${tag(isLocked()?'Administrator review required':'Server risk checks active',isLocked()?'red':'')}<p class="metric-bottom">${isLocked()?'New transfers are disabled.':'An active account still requires a check for each transfer.'}</p></div><div class="card"><div class="card-head"><span>Total sent</span><div class="status-icon purple">${icon('send')}</div></div><div class="metric-value">${money(state.data.outgoing_minor)}</div><p class="metric-bottom">Completed transfers only.<br>Held or blocked transfers are excluded.</p></div></section><div class="dashboard-grid"><div class="stack"><section class="card">${sectionTitle('Transfer simulated funds','Amounts are stored in cents; debit and credit are applied together.')}<div class="quick-people">${state.recipients.map(r=>`<button class="person" data-recipient="${esc(r.id)}"><span class="avatar">${esc(initials(r.full_name))}</span>${esc(r.full_name.split(' ')[0])}</button>`).join('')}</div>${transferForm()}</section><section class="card">${sectionTitle('Recent activity','Completed, held and blocked transfers.')}${transactions()}</section></div><div class="stack"><section class="card">${sectionTitle('Three levels. Three responses.')}<div class="tier-mini"><span class="tier-dot green"></span><div><strong>Low → Allow</strong><p>Within the user reference; the transfer may proceed.</p></div></div><div class="tier-mini"><span class="tier-dot amber"></span><div><strong>Medium → Step-up</strong><p>Verify again; funds have not moved.</p></div></div><div class="tier-mini"><span class="tier-dot red"></span><div><strong>High → Block</strong><p>Block the transfer, lock the account and record an alert.</p></div></div></section><section class="card insight-card"><div class="eyebrow">SUPERVISOR PRESENTATION</div><h3>Explain the research.<br>Show the evidence.</h3><p>Start with the problem, methodology and two models, then demonstrate the decision flow.</p><button class="btn soft" data-page="presentation">Open presentation mode ${icon('arrow')}</button></section><section class="card">${sectionTitle('Security timeline')}${timeline(state.data.events,3)}</section></div></div>`;}
function transferPage(){return greeting('Transfers with behavioural checks.','Funds move only after the server approves the transfer.')+lockedNotice()+pendingNotice()+coldStartNotice()+`<div class="two-col"><section class="card">${sectionTitle('New transfer','Simulated funds between research accounts only.')}${transferForm()}</section><section class="card">${sectionTitle('What does the server check?')}<div class="step-list"><div class="step"><span class="step-number">1</span><div><strong>Check the account and session</strong><p>Locked accounts cannot transfer funds. Unlocking an account revokes its previous customer sessions.</p></div></div><div class="step"><span class="step-number">2</span><div><strong>Compare with the user reference</strong><p>Isolation Forest and One-Class SVM learn from the target user’s genuine training sessions only. Incomplete input requires further checks.</p></div></div><div class="step"><span class="step-number">3</span><div><strong>Allow, verify again or block</strong><p>Thresholds are calibrated using genuine validation data for each user and model.</p></div></div></div><button class="btn soft full" data-page="security" style="margin-top:24px">View the three guided scenarios</button></section></div><section class="card" style="margin-top:23px">${sectionTitle('Transfer history')}${transactions()}</section>`;}
function modelSelect(id='scenario-model'){return `<div class="model-selector"><label for="${id}">Demonstration model</label><select id="${id}" data-model-select>${['isolation_forest','one_class_svm'].map(key=>`<option value="${key}" ${state.selectedModel===key?'selected':''}>${modelName(key)}</option>`).join('')}</select><span class="small muted">Both models are fitted per user. Select a model to compare the demonstration responses.</span></div>`;}
function scenarioCards(){const disabled=state.user.role!=='customer'||state.user.id!=='demo-irfan'||isLocked()||!syntheticMode();return `<div class="scenario-grid"><section class="card scenario"><span class="status-tag">01 / LOW RISK</span><br><br>${icon('check')}<h2>Normal</h2><p>Replay a generated reference sample within the demonstration user’s baseline.</p><div class="scenario-outcome">Expected: <strong>Allow</strong><small>The balance changes only after the server decision.</small></div><button class="btn primary full" data-scenario="normal" ${disabled?'disabled':''}>Run normal scenario</button></section><section class="card scenario"><span class="status-tag amber">02 / MEDIUM RISK</span><br><br>${icon('shield')}<h2>Verification required</h2><p>Replay a sample between the selected model’s review and block thresholds.</p><div class="scenario-outcome">Expected: <strong>Step-up</strong><small>The transfer is held. No debit occurs before verification.</small></div><button class="btn amber full" data-scenario="medium" ${disabled?'disabled':''}>Run medium scenario</button></section><section class="card scenario danger-scenario"><span class="status-tag red">03 / HIGH RISK</span><br><br>${icon('lock')}<h2>Strong anomaly</h2><p>Replay a sample outside the baseline to demonstrate blocking, alerts and account locking.</p><div class="scenario-outcome">Expected: <strong>Block + lock</strong><small>The balance is unchanged. An administrator must review the account.</small></div><button class="btn danger full" data-scenario="high" ${disabled?'disabled':''}>Run high scenario</button></section></div>${disabled?'<p class="metrics-note">Replay scenarios require generated reference artifacts and an active Customer demo account. Imported CSV data does not use these scenario inputs. Administrators can inspect models and audit records without acting as customers.</p>':''}`;}
function decisionExplanation(result=state.lastScenario){
  if(!result)return '';
  const t=result.transaction||{},details=t.decision_details||result.decision_details||{},tier=t.tier||details.tier||result.tier;
  const scored=details.score_available!==false,thresholds=details.raw_thresholds,verification=details.verification;
  const assessmentRows=Object.entries(details.assessments||{});
  return `<section class="card decision-card"><div class="section-head"><div><div class="eyebrow">SERVER DECISION</div><h2>${esc(tierLabel(tier||({completed:'allow',step_up_required:'step_up',blocked:'block'}[result.status])))}</h2></div>${tag(statusLabel(t.status||result.status),t.status==='blocked'?'red':result.status==='step_up_required'?'amber':'')}</div><div class="decision-stats"><div><span>Assessment method</span><strong>${details.policy_score_available?'PIN rhythm check':scored?esc(modelName(t.model_name||details.model_name||state.selectedModel)):'Not assessed'}</strong></div><div><span>Raw anomaly score</span><strong>${scoreText(t,'model_score')}</strong></div><div><span>Genuine validation percentile</span><strong>${scoreText(t,'risk_score')}</strong></div><div><span>Amount</span><strong>${money(t.amount_minor)}</strong></div></div>${thresholds?`<div class="threshold-box"><div><span>User/model review threshold</span><strong>${raw(thresholds.review)}</strong></div><div><span>User/model block threshold</span><strong>${raw(thresholds.block)}</strong></div></div>`:''}<p class="metrics-note">${details.policy_score_available?'Measured PIN timing was compared with the enrolled reference. This check does not establish identity.':scored?'The percentile ranks the input against genuine validation sessions. It is <strong>not a fraud probability</strong>. Raw scores from the two models are not directly comparable.':'Additional verification or an enrolled reference is required for this decision.'}</p>${assessmentRows.length?`<div class="table-wrap"><table class="comparison-table"><thead><tr><th>MODEL / SAME INPUT</th><th>RAW SCORE</th><th>PERCENTILE</th><th>LEVEL</th></tr></thead><tbody>${assessmentRows.map(([key,a])=>`<tr><td>${esc(modelName(key))}${key===details.model_name?' *':''}</td><td>${raw(a.model_score)}</td><td>${pct(a.risk_score)}</td><td>${esc(tierLabel(a.tier))}</td></tr>`).join('')}</tbody></table></div><p class="metrics-note">* The selected model determines the transaction action. The models may assess the same input differently.</p>`:''}<ul class="decision-reasons">${(t.reasons||details.reasons||[]).map(reason=>`<li>${esc(displayText(reason))}</li>`).join('')}</ul>${verification?`<div class="notice stepup-notice" style="margin-top:18px;margin-bottom:0"><strong>${verification.approved?'Additional verification approved':'Verification cancelled'}</strong> · ${esc(verification.method)}. The original score and risk level remain in the audit record; verification is recorded separately.</div>`:''}${result.status==='step_up_required'?'<button class="btn amber" data-resume-stepup style="margin-top:18px">Continue demonstration verification</button>':''}</section>`;
}
function securityPage(){return greeting('See how decisions are made.','Scenarios use generated reference profiles; the server enforces the decisions and simulated balance changes.')+lockedNotice()+pendingNotice()+modelSelect()+scenarioCards()+decisionExplanation()+`<section class="card" style="margin-top:23px">${sectionTitle('Decision timeline','Anomaly percentiles and raw scores are recorded separately.')}${timeline(state.data.events,20)}</section><div class="notice" style="margin-top:23px;margin-bottom:0"><strong>During the presentation:</strong> scenario buttons select known demonstration inputs to test the system flow. They do not establish detection of real attackers. Device restrictions and security rules are separate controls.</div>`;}
function profile(){return state.model?.users?.[state.researchUser]||Object.values(state.model?.users||{})[0];}
function profileControls(){const users=Object.keys(state.model?.users||{});return `<div class="research-controls"><div><label for="research-user">Displayed baseline</label><select id="research-user">${users.map(key=>`<option ${key===state.researchUser?'selected':''} value="${esc(key)}">${esc(key)}</option>`).join('')}</select></div><span class="small muted">Each identity has its own training data, scaler and two models.</span></div>`;}
function comparison(){const p=profile();if(!p)return '<div class="notice">No trained model is available for this account. Evaluation metrics are not yet available.</div>';return `<div class="table-wrap"><table class="comparison-table"><thead><tr><th>MODEL</th><th>EER ↓</th><th>FAR ↓</th><th>FRR ↓</th><th>ROC-AUC ↑</th></tr></thead><tbody>${Object.entries(p.models||{}).map(([key,m])=>`<tr><td><strong>${esc(modelName(key))}</strong><small>${esc(key)}</small></td><td>${pct(m.eer)}</td><td>${pct(m.far)}</td><td>${pct(m.frr)}</td><td>${Number.isFinite(m.roc_auc)?m.roc_auc.toFixed(4):'—'}</td></tr>`).join('')}</tbody></table></div><p class="metrics-note">Metrics are calculated on held-out test sessions. FAR/FRR and the confusion matrix use the review threshold, including sessions that require step-up. EER estimates the point where FAR and FRR meet. Test data does not tune thresholds or select the serving model; Isolation Forest is the fixed demonstration default.</p>`;}
function metricGlossary(){return `<div class="glossary-grid"><div><strong>EER ↓</strong><p>The point where the impostor acceptance rate is close to the genuine rejection rate. Lower is better.</p></div><div><strong>FAR ↓</strong><p>How often impostor sessions are accepted as genuine. This measures an evaluation security error.</p></div><div><strong>FRR ↓</strong><p>How often genuine sessions are rejected or flagged, potentially interrupting legitimate users.</p></div><div><strong>ROC-AUC ↑</strong><p>Ranking of genuine and impostor sessions across thresholds. This is not the probability that an operator is an attacker.</p></div></div>`;}
function modelDetail(key,m){const matrix=m.confusion_matrix||[[0,0],[0,0]];return `<section class="card"><div class="section-head"><h2>${esc(modelName(key))}</h2>${tag('GENUINE-ONLY','purple')}</div><p class="small muted">${key==='isolation_forest'?'Unusual samples are more easily isolated by random trees.':'Learns a boundary around genuine patterns after standardisation.'}</p><div class="threshold-box"><div><span>Review threshold</span><strong>${raw(m.thresholds?.review)}</strong></div><div><span>Block threshold</span><strong>${raw(m.thresholds?.block)}</strong></div></div><p class="metrics-note">Thresholds use this model’s raw score scale and genuine validation data. Scales differ across models and users.</p><div class="matrix"><div><strong>${matrix[0][0]}</strong><span>Genuine → accepted</span></div><div class="error"><strong>${matrix[0][1]}</strong><span>Genuine → flagged</span></div><div class="error"><strong>${matrix[1][0]}</strong><span>Impostor → accepted</span></div><div><strong>${matrix[1][1]}</strong><span>Impostor → flagged</span></div></div></section>`;}
function labPage(){const p=profile(),counts=p?.counts||{};return greeting('Two models. One clear protocol.','Report methodology §3.5: genuine-only, per-user training with separate genuine and impostor testing.')+`<div class="notice"><strong>${syntheticMode()?'Generated reference data only.':'Imported CSV data.'}</strong> ${esc(dataNarrative())} These metrics do not establish real-world performance.</div>${profileControls()}<section class="stat-grid"><div class="card"><span class="small muted">Genuine training</span><div class="metric-value">${counts.train_genuine??'—'}</div><p class="metric-bottom">No impostor sessions are used to fit the model or scaler.</p></div><div class="card"><span class="small muted">Genuine validation</span><div class="metric-value">${counts.validation_genuine??'—'}</div><p class="metric-bottom">Used to calibrate review and block thresholds.</p></div><div class="card"><span class="small muted">Test held-out</span><div class="metric-value">${p?(counts.test_genuine||0)+(counts.test_impostor||0):'—'}</div><p class="metric-bottom">${counts.test_genuine??0} genuine + ${counts.test_impostor??0} impostor</p></div></section><section class="card">${sectionTitle('Model comparison','Values from the evaluation run loaded by the server.')}${comparison()}</section><div class="two-col" style="margin-top:23px">${Object.entries(p?.models||{}).map(([key,m])=>modelDetail(key,m)).join('')}</div><section class="card" style="margin-top:23px">${sectionTitle('How to read the results')}${metricGlossary()}</section><section class="card" style="margin-top:23px">${sectionTitle('Required behavioural features')}<div class="feature-chips">${(state.model?.features||[]).map(f=>`<span>${esc(f)}</span>`).join('')}</div><p class="metrics-note">Dwell/flight timing, swipe, touch pressure and accelerometer/gyroscope/tilt summaries. Device, amount and recipient context belong to separate policies and do not establish identity recognition.</p></section>`;}
const slides=[['Problem & objectives','Why is this research needed?'],['Methodology','What is trained and tested?'],['Two models','How are results compared?'],['Live demonstration','Show the three action levels.'],['Administrator review','Show that held funds do not move.'],['Limits & next steps','What can and cannot be concluded?']];
function presentationBody(){
  if(state.slide===0)return `<section class="present-hero"><div class="eyebrow">FYP / BEHAVIOURAL BIOMETRICS</div><h2>After login,<br><em>who is using the account?</em></h2><p>A correct password does not by itself establish who is interacting. This project explores behavioural changes during a simulated banking session.</p><div class="present-tags">${tag('Per-user baseline','purple')}${tag('Genuine-only training','purple')}${tag('Risk-based response','purple')}</div></section><div class="three-col"><section class="card"><span class="objective-number">01</span><h3>Represent behaviour</h3><p>Convert timing, touch and sensor readings into numeric features without storing typed content.</p></section><section class="card"><span class="objective-number">02</span><h3>Learn genuine behaviour</h3><p>Fit per-user Isolation Forest and One-Class SVM models using genuine training sessions only.</p></section><section class="card"><span class="objective-number">03</span><h3>Evaluate and demonstrate actions</h3><p>Compare EER, FAR, FRR and ROC-AUC, then demonstrate allow, step-up and block responses.</p></section></div><div class="speaker-note"><strong>Presentation note</strong><p>“The project demonstrates a pipeline and evaluation of behavioural anomaly detection in simulated mobile banking. It does not establish a new algorithm or production banking security.”</p></div>`;
  if(state.slide===1)return `<section class="card">${sectionTitle('Research pipeline','Aligned with report §3.5–3.9. The demonstration UI and evaluation dataset have separate roles.')}<div class="pipeline"><div><b>1</b><strong>Behavioural features</strong><small>Dwell · flight · swipe · pressure · sensors</small></div><span>→</span><div><b>2</b><strong>Per-user models</strong><small>Isolation Forest + One-Class SVM</small></div><span>→</span><div><b>3</b><strong>Anomaly score</strong><small>Compare with the genuine reference</small></div><span>→</span><div><b>4</b><strong>Tiered actions</strong><small>Allow · step-up · block</small></div></div></section><div class="three-col" style="margin-top:23px"><section class="card split-card"><span class="split-label train">TRAIN</span><h3>Genuine only</h3><p>Fit the scaler and models using the target user’s genuine sessions, without impostor sessions.</p></section><section class="card split-card"><span class="split-label validation">VALIDATION</span><h3>Calibrate thresholds</h3><p>Use separate genuine validation sessions to set each user/model’s review and block thresholds.</p></section><section class="card split-card"><span class="split-label test">TEST</span><h3>Held-out evaluation</h3><p>Use separate genuine sessions and other users’ sessions as impostors. Never put test sessions back into training.</p></section></div><div class="notice" style="margin-top:23px"><strong>Current data source:</strong> ${esc(dataNarrative())} The dataset import pipeline is available. Research conclusions still require a selected source, documented feature mapping, protocol and permitted use.</div><div class="speaker-note"><strong>Presentation note</strong><p>“Each user has an individual reference. Models learn only from genuine training sessions; impostor sessions test whether the learned boundary separates other users.”</p></div>`;
  if(state.slide===2)return `${profileControls()}<div class="two-col"><section class="card"><div class="eyebrow">MODEL A</div><h2>Isolation Forest</h2><p class="present-copy">Builds trees with random splits. Unusual sessions tend to require fewer splits to isolate.</p><div class="analogy">Analogy: a point far from the group is easier to separate.</div></section><section class="card"><div class="eyebrow">MODEL B</div><h2>One-Class SVM</h2><p class="present-copy">Learns a boundary around genuine feature distributions. Sessions outside that boundary are more anomalous.</p><div class="analogy">Analogy: draw the usual region, then check whether a new session falls inside it.</div></section></div><section class="card" style="margin-top:23px">${sectionTitle(syntheticMode()?'Comparison evidence — generated reference data':'Comparison evidence — imported CSV')}${comparison()}${metricGlossary()}</section><div class="speaker-note"><strong>Presentation note</strong><p>“Neither model is assumed to be better. Both are evaluated under the same protocol. Results depend on the data source and protocol; CSV import alone does not validate labels or real-world performance.”</p></div>`;
  if(state.slide===3)return `<div class="present-demo-intro"><h2>Three inputs. Three server actions.</h2><p>Run normal first, then medium with demonstration verification. Run high last because it locks the account.</p></div>${state.user.role==='customer'?lockedNotice()+pendingNotice():''}${modelSelect('present-model')}${scenarioCards()}${decisionExplanation()}<div class="speaker-note"><strong>What to show the supervisor</strong><p>Normal changes the balance once. Medium holds funds until verification. High does not debit funds and prevents further transfers. Web demonstration approval is a labelled simulation, separate from native device biometrics.</p></div>`;
  if(state.slide===4)return `<div class="two-col"><section class="card">${sectionTitle('Explainable audit trail')}<div class="step-list"><div class="step"><span class="step-number">1</span><div><strong>Review the decision and reasons</strong><p>Server records distinguish the model, raw anomaly score, genuine percentile and policy reasons.</p></div></div><div class="step"><span class="step-number">2</span><div><strong>Confirm the balance stays unchanged</strong><p>Blocked or pending transfers do not debit or credit either account.</p></div></div><div class="step"><span class="step-number">3</span><div><strong>Administrators record review reasons</strong><p>Unlock revokes previous customer sessions. It does not automatically trust a new device.</p></div></div></div><button class="btn primary full" style="margin-top:25px" data-page="${state.user.role==='admin'?'admin':'security'}">${state.user.role==='admin'?'Open Security overview':'View the customer timeline'} ${icon('arrow')}</button></section><section class="card">${sectionTitle('Latest records','Recorded activity in the simulation database.')}${timeline(state.data.events,6)}</section></div><div class="speaker-note"><strong>Presentation note</strong><p>“Models help assess anomalies; the server enforces decisions. Hiding UI buttons alone cannot protect a transfer.”</p></div>`;
  return `<section class="card research-boundary">${sectionTitle('What does the prototype demonstrate?')}<div class="boundary-row"><span class="boundary-symbol yes">✓</span><div><strong>Per-user genuine-only pipeline</strong><p>Two models, separate validation, held-out metrics and three risk actions are implemented.</p></div></div><div class="boundary-row"><span class="boundary-symbol yes">✓</span><div><strong>Testable application flow</strong><p>Web and Android use the server for transfers, holds, blocks, account locks and administrator review.</p></div></div><div class="boundary-row"><span class="boundary-symbol no">!</span><div><strong>Real attacker detection is not established</strong><p>${syntheticMode()?'The current data is generated reference data.':'CSV provenance requires validation.'} Client timing and device information can be falsified. An anomaly score is not identity proof or a calibrated fraud probability.</p></div></div><div class="boundary-row"><span class="boundary-symbol no">!</span><div><strong>Production assurance remains unverified</strong><p>Web step-up demonstrates the flow. Native device-key proofs require physical-phone validation; attestation and verified recovery remain separate work.</p></div></div></section><div class="three-col" style="margin-top:23px"><section class="card"><span class="objective-number">NEXT / 01</span><h3>Public datasets</h3><p>Select a real source, check its licence and document feature mapping and disjoint session/time splits.</p></section><section class="card"><span class="objective-number">NEXT / 02</span><h3>Valid evaluation</h3><p>Report FAR, FRR, EER and ROC-AUC; analyse per-user variation, false positives and incomplete sensor input.</p></section><section class="card"><span class="objective-number">NEXT / 03</span><h3>Integration and recovery</h3><p>Test real phones and sensors, validate step-up and establish trusted device enrolment.</p></section></div><div class="speaker-note"><strong>Closing presentation note</strong><p>“The prototype demonstrates an executable pipeline and transaction controls. Model effectiveness still requires an appropriate behavioural dataset, a sound protocol and error analysis.”</p></div>`;
}
function presentationPage(){return `<div class="presentation-heading"><div><div class="eyebrow">SUPERVISOR PRESENTATION GUIDE</div><h1>${slides[state.slide][0]}</h1><p>${slides[state.slide][1]}</p></div><span class="slide-count">${String(state.slide+1).padStart(2,'0')} <span>/ ${slides.length}</span></span></div><nav class="slide-tabs" aria-label="Presentation steps">${slides.map(([title],index)=>`<button data-slide="${index}" class="${state.slide===index?'active':''}" ${state.slide===index?'aria-current="step"':''}>${index+1}. ${title}</button>`).join('')}</nav>${presentationBody()}<div class="slide-footer"><button class="btn" id="slide-prev" ${state.slide===0?'disabled':''}>← Previous</button><span>Use the tabs or buttons to follow the presentation flow.</span><button class="btn primary" id="slide-next" ${state.slide===slides.length-1?'disabled':''}>Next →</button></div>`;}
function pendingReviewTable(){const rows=state.data.pending_transfers||[];return `<section class="card" style="margin-top:23px">${sectionTitle('Transfers awaiting review','Held transfers do not debit funds. Administrator approval cannot override a missing required reference.')}<div class="table-wrap"><table class="admin-table"><thead><tr><th>CUSTOMER / AMOUNT</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${rows.map(t=>`<tr><td><strong>${esc(t.full_name)}</strong><p class="small muted">${money(t.amount_minor)} · ${esc(t.id.slice(0,8))}</p></td><td>${tag(statusLabel(t.status),'amber')}</td><td>${t.status==='step_up_required'?`<div class="review-actions"><button class="btn soft" data-review="${esc(t.id)}" data-approved="true">Approve after review</button><button class="btn" data-review="${esc(t.id)}" data-approved="false">Cancel</button></div>`:'<span class="small muted">Enrolment data required</span>'}</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">No pending transfers.</div>':''}</div></section>`;}
function adminPage(){const d=state.data;return greeting('Review the reasons before unlocking.','Administrator actions are recorded. Unlock revokes previous customer sessions.')+`<section class="stat-grid"><div class="card"><span class="small muted">Locked accounts</span><div class="metric-value">${d.users.filter(u=>u.status==='locked').length}</div></div><div class="card"><span class="small muted">Blocked transfers</span><div class="metric-value">${d.blocked_count}</div></div><div class="card"><span class="small muted">Blocked transfer attempts</span><div class="metric-value">${money(d.protected_minor)}</div></div></section><section class="card"><div class="section-head"><h2>Account review queue</h2><button class="text-button" id="admin-refresh">Refresh ↻</button></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>ACCOUNT</th><th>STATUS</th><th>REVIEW</th></tr></thead><tbody>${d.users.map(u=>`<tr><td><div class="recipient-cell"><span class="avatar">${esc(initials(u.full_name))}</span><div><strong>${esc(u.full_name)}</strong><small>${esc(u.email)}</small></div></div></td><td>${tag(u.status==='locked'?'Locked':'Active',u.status==='locked'?'red':'')}</td><td>${u.status==='locked'?`<button class="btn soft" data-unlock="${esc(u.id)}">Review & unlock</button>`:'<span class="small muted">No action required</span>'}</td></tr>`).join('')}</tbody></table></div></section>${pendingReviewTable()}<section class="card" style="margin-top:23px">${sectionTitle('Risk decision audit','Raw scores and anomaly percentiles use different scales.')}<div class="table-wrap"><table><thead><tr><th>ACCOUNT / REASON</th><th>RAW SCORE</th><th>GENUINE PERCENTILE</th><th>TIME (MYT)</th></tr></thead><tbody>${(d.events||[]).map(e=>`<tr><td><strong>${esc(e.full_name)}</strong><p class="small muted">${esc(displayText(e.kind.replaceAll('_',' ')))}</p><p class="small muted">${esc(e.reasons.map(displayText).join('; '))}</p></td><td>${scoreText(e,'model_score')}</td><td>${tag(scoreText(e,'risk_score'),e.severity==='critical'||e.tier==='block'?'red':e.tier==='step_up'||e.severity==='warning'?'amber':'')}</td><td>${date(e.created_at)}</td></tr>`).join('')}</tbody></table>${!d.events?.length?'<div class="empty">Run a customer scenario to generate records.</div>':''}</div></section><div class="notice" style="margin-top:23px">The demonstration administrator password is public. Real-world identity checks are outside this prototype. Unlock does not enrol a new trusted device.</div>`;}
function render(){
  const pages={overview,transfer:transferPage,security:securityPage,lab:labPage,presentation:presentationPage,admin:adminPage};app.innerHTML=shell(pages[state.page]());
  app.querySelector('.sidebar-bottom').insertAdjacentHTML('afterbegin',`<a class="btn soft full" href="${basePath}/pin-demo">PIN rhythm practice</a>`);
  app.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;render();window.scrollTo(0,0);});
  app.querySelectorAll('[data-logout]').forEach(b=>b.onclick=async()=>{try{await api('/auth/logout',{});}catch{}state.user=null;state.pending=null;authScreen();});
  app.querySelectorAll('[data-recipient]').forEach(b=>b.onclick=()=>{$('#recipient').value=b.dataset.recipient;$('#amount').focus();});
  app.querySelectorAll('[data-model-select]').forEach(s=>s.onchange=()=>{state.selectedModel=s.value;});
  app.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>runScenario(b.dataset.scenario));
  app.querySelectorAll('[data-slide]').forEach(b=>b.onclick=()=>{state.slide=Number(b.dataset.slide);render();window.scrollTo(0,0);});
  if($('#slide-prev'))$('#slide-prev').onclick=()=>{state.slide--;render();window.scrollTo(0,0);};if($('#slide-next'))$('#slide-next').onclick=()=>{state.slide++;render();window.scrollTo(0,0);};
  if($('#research-user'))$('#research-user').onchange=e=>{state.researchUser=e.target.value;render();};
  if($('#transfer-form'))$('#transfer-form').onsubmit=sendTransfer;
  app.querySelectorAll('[data-resume-stepup]').forEach(b=>b.onclick=()=>showStepUp(state.pending||state.lastScenario));
  if($('#admin-refresh'))$('#admin-refresh').onclick=()=>safeRefresh();
  app.querySelectorAll('[data-review]').forEach(b=>b.onclick=async()=>{const reason=prompt('Record a reason after a separate review (at least 10 characters). This prototype review does not establish a person’s identity.');if(!reason)return;if(reason.trim().length<10){toast('Enter a reason with at least 10 characters.');return;}b.disabled=true;try{await api(`/admin/transfers/${encodeURIComponent(b.dataset.review)}/review`,{approved:b.dataset.approved==='true',reason});toast('Review decision recorded.');await refresh();}catch(error){toast(error.message);await safeRefresh();}});
  app.querySelectorAll('[data-unlock]').forEach(b=>b.onclick=async()=>{const reason=prompt('Record the review reason (at least 10 characters). Use fictional details in this research prototype.');if(!reason)return;if(reason.trim().length<10){toast('Enter a review reason with at least 10 characters.');return;}b.disabled=true;try{const r=await api(`/admin/users/${encodeURIComponent(b.dataset.unlock)}/unlock`,{reason});toast(r.message);await refresh();}catch(error){toast(error.message);b.disabled=false;}});
}
async function safeRefresh(){try{await refresh();}catch(error){if(error.status===401){state.user=null;authScreen();}toast(error.message);}}
async function runScenario(scenario){
  if(state.busy)return;if(scenario==='high'&&!confirm('The high-risk scenario will block the transfer and lock the demonstration account. An administrator must unlock it. Continue?'))return;
  state.busy=true;app.querySelectorAll('[data-scenario]').forEach(b=>b.disabled=true);
  try{const result=await api('/demo/scenario',{scenario,model:state.selectedModel});state.lastScenario=result;await refresh();handleTransferResult(result);}catch(error){toast(error.message);await safeRefresh();}finally{state.busy=false;}
}
let transferAttempt=null;
async function sendTransfer(e){
  e.preventDefault();if(state.busy)return;const input=$('#amount').value.trim();if(!/^\d+(\.\d{1,2})?$/.test(input)){$('#transfer-error').textContent='Enter an amount with up to two decimal places.';return;}
  const [whole,decimal='']=input.split('.'),amount=Number(whole)*100+Number(decimal.padEnd(2,'0'));if(!Number.isSafeInteger(amount)||amount<1||amount>10000000){$('#transfer-error').textContent='The amount must be between RM 0.01 and RM 100,000.';return;}
  const recipient=$('#recipient').value,name=state.recipients.find(r=>r.id===recipient)?.full_name;if(!confirm(`Send ${money(amount)} in simulated funds to ${name}? The transfer may be held for verification.`))return;
  const key=`${recipient}:${amount}`;if(!transferAttempt||transferAttempt.key!==key)transferAttempt={key,id:uid()};state.busy=true;const button=e.target.querySelector('[type=submit]');button.disabled=true;
  try{const result=await api('/transfers',{recipient_id:recipient,amount_minor:amount,request_id:transferAttempt.id,telemetry:telemetry.snapshot()});transferAttempt=null;telemetry.reset();state.lastScenario=result;await refresh();handleTransferResult(result);}catch(error){if($('#transfer-error'))$('#transfer-error').textContent=error.message;else toast(error.message);if(error.status===423)await safeRefresh();}finally{state.busy=false;button.disabled=isLocked();}
}
function transferAssessmentRows(t){
  const details=t.decision_details||{},timing=details.pin_timing;
  if(details.policy_score_available){
    return [['Assessment','PIN rhythm check'],...(timing?[
      ['Average press',`${Math.round(timing.mean_dwell_ms)} ms`],
      ['Average gap',`${Math.round(timing.mean_flight_ms)} ms`]
    ]:[])];
  }
  if(details.score_available===false)return [['Behavioural assessment','Not assessed'],['Next step','Additional verification']];
  return [['Assessment',modelName(t.model_name||details.model_name||state.selectedModel)],['Genuine validation percentile',scoreText(t,'risk_score')],['Raw anomaly score',scoreText(t,'model_score')]];
}
function handleTransferResult(result){
  const t=result.transaction||{};if(result.status==='step_up_required'||t.status==='pending'||t.status==='step_up_required'){state.pending={...result,challenge_id:result.challenge_id||t.challenge_id};showStepUp(state.pending);return;}
  if(result.status==='enrollment_required'||t.status==='enrollment_required'){modal('Behavioural reference unavailable.','Funds have not moved. An account PIN or phone biometric does not train a behavioural model. You can try the separate PIN rhythm exercise using generated reference data. Use practice PIN 246810, not your transaction PIN. The exercise compares timing; it does not verify identity or approve a transfer.',[],'amber',`<a class="btn primary full" id="open-pin-demo" href="${basePath}/pin-demo" style="margin-bottom:12px;text-decoration:none">PIN rhythm practice</a>`);$('#dialog-close').textContent='Back';return;}
  const blocked=t.status==='blocked';modal(blocked?'Transfer blocked. Funds safe.':t.status==='cancelled'?'Transfer cancelled.':'Transfer complete.',blocked?'The server blocked the transfer and locked the account for review. Funds have not moved.':t.status==='cancelled'?'Verification was cancelled. Funds have not moved.':'Simulated funds were transferred after the required checks and verification.',[['Amount',money(t.amount_minor)],...transferAssessmentRows(t),['Reference',String(t.id||'—').slice(0,8)]],blocked?'red':'');
}
function showStepUp(pending){
  const challenge=pending?.challenge_id||pending?.id,t=pending?.transaction||pending||{},demo=state.user.id==='demo-irfan';
  modal('Additional verification required.','The transfer is held and the balance is unchanged. Additional verification is required before it can proceed.',[['Amount',money(t.amount_minor)],...transferAssessmentRows(t)],'amber',`<div class="stepup-demo-label"><strong>${demo?'DEMONSTRATION STEP-UP':'SEPARATE VERIFICATION REQUIRED'}</strong><p>${demo?'These buttons simulate an additional review for the public demonstration account. They do not perform device biometrics or establish identity.':'This account requires its enrolled device biometric flow or a separate administrator review.'}</p></div>${demo&&challenge?'<button class="btn amber full" id="approve-stepup">Simulate successful verification</button>':''}${demo&&challenge?'<button class="btn full" id="cancel-stepup" style="margin-top:9px">Cancel pending transfer</button>':''}`);
  if($('#approve-stepup'))$('#approve-stepup').onclick=()=>verifyStepUp(challenge,true);
  if($('#cancel-stepup'))$('#cancel-stepup').onclick=()=>verifyStepUp(challenge,false);
}
async function verifyStepUp(challenge,approved){
  if(state.busy)return;state.busy=true;$('#dialog-content').querySelectorAll('button').forEach(b=>b.disabled=true);
  try{const result=await api(`/step-up/${encodeURIComponent(challenge)}/verify`,{method:'demo',approved});state.pending=null;state.lastScenario=result;await refresh();handleTransferResult(result);}catch(error){toast(error.message);}finally{state.busy=false;$('#dialog-content').querySelectorAll('button').forEach(b=>b.disabled=false);}
}
// Bounded timing summaries only; no key values, passwords or raw pointer paths are transmitted.
const telemetry={intervals:[],holds:[],speeds:[],down:new Map(),lastDown:0,lastPointer:null,
  reset(){this.intervals=[];this.holds=[];this.speeds=[];this.down.clear();this.lastDown=0;this.lastPointer=null;},
  snapshot(){const mean=a=>a.length?a.reduce((x,y)=>x+y,0)/a.length:null;return{typing_interval_ms:mean(this.intervals),key_hold_ms:mean(this.holds),pointer_speed:mean(this.speeds),samples:Math.min(10000,Math.max(this.intervals.length,this.speeds.length))};}};
document.addEventListener('keydown',e=>{if(!e.target.closest('#transfer-form')||e.target.type==='password'||e.repeat)return;const t=performance.now();if(telemetry.lastDown){const d=t-telemetry.lastDown;if(d>=10&&d<=5000)telemetry.intervals.push(d);}telemetry.lastDown=t;telemetry.down.set(e.code,t);telemetry.intervals=telemetry.intervals.slice(-100);});
document.addEventListener('keyup',e=>{if(!e.target.closest('#transfer-form'))return;const start=telemetry.down.get(e.code);if(start){const hold=performance.now()-start;if(hold>=5&&hold<=3000)telemetry.holds.push(hold);telemetry.holds=telemetry.holds.slice(-100);telemetry.down.delete(e.code);}});
document.addEventListener('pointermove',e=>{if(!e.target.closest('#transfer-form'))return;const t=performance.now(),last=telemetry.lastPointer;if(last&&t-last.t<80)return;if(last){const speed=Math.hypot(e.clientX-last.x,e.clientY-last.y)/(t-last.t)*1000;if(speed<=20000)telemetry.speeds.push(speed);telemetry.speeds=telemetry.speeds.slice(-100);}telemetry.lastPointer={x:e.clientX,y:e.clientY,t};});
async function init(){app.innerHTML='<div class="loading">Opening workspace…</div>';try{state.user=await api('/me');state.page=state.user.role==='admin'?'admin':'overview';await refresh();}catch{authScreen();}}
init();
